import java.io.*;
import java.util.*;
public class G{
    public static void main(String[] args) {
        G instance = new G();
        instance.begin();
    }

    void begin() {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        Problem problem = new Problem();
        problem.run(1, in, out);
        out.flush();
        out.close();
    }

    static class Problem {
        static class MinCostFlow {
            static class Edge {
                int to, cap, rev, cost;
                Edge(int t, int c, int w, int r) {
                    to = t; cap = c; cost = w; rev = r;
                }
            }

            List<Edge>[] adj;
            Edge[][] edgeMatrix;
            int[] potential;
            int N, source, sink, flow;
            long totalCost;
            final int INF = Integer.MAX_VALUE / 2;

            MinCostFlow(int nodes, int s, int t) {
                N = nodes; source = s; sink = t;
                flow = 0; totalCost = 0;
                adj = new ArrayList[N];
                potential = new int[N];
                for(int i = 0; i < N; i++) adj[i] = new ArrayList<>();
            }

            void addEdge(int u, int v, int capacity, int weight) {
                Edge forward = new Edge(v, capacity, weight, adj[v].size());
                Edge backward = new Edge(u, 0, -weight, adj[u].size());
                adj[u].add(forward);
                adj[v].add(backward);
            }

            void packEdges() {
                edgeMatrix = new Edge[N][];
                for(int i = 0; i < N; i++) {
                    edgeMatrix[i] = adj[i].toArray(new Edge[0]);
                    adj[i].clear();
                }
            }

            void initializePotential() {
                Arrays.fill(potential, INF);
                potential[source] = 0;
                boolean changed = true;
                for(int iter = 0; iter < N && changed; iter++) {
                    changed = false;
                    for(int u = 0; u < N; u++) {
                        if(potential[u] == INF) continue;
                        for(Edge e : edgeMatrix[u]) {
                            if(e.cap > 0 && potential[u] + e.cost < potential[e.to]) {
                                potential[e.to] = potential[u] + e.cost;
                                changed = true;
                            }
                        }
                    }
                }
            }

            int[] prevNode, prevEdge, visited, distArray;
            int[] queueBuffer;

            boolean performSPFA() {
                distArray = new int[N];
                prevNode = new int[N];
                prevEdge = new int[N];
                visited = new int[N];
                queueBuffer = new int[N];
                Arrays.fill(distArray, INF);
                distArray[source] = 0;
                int head = 0, tail = 0;
                queueBuffer[tail++] = source;
                while(head != tail) {
                    int u = queueBuffer[head++];
                    if(head == N) head = 0;
                    visited[u] = 2;
                    for(int idx = 0; idx < edgeMatrix[u].length; idx++) {
                        Edge e = edgeMatrix[u][idx];
                        if(e.cap == 0) continue;
                        int nd = distArray[u] + e.cost;
                        if(nd < distArray[e.to]) {
                            if(visited[e.to] == 0) {
                                queueBuffer[tail++] = e.to;
                                if(tail == N) tail = 0;
                            } else if(visited[e.to] == 2) {
                                if(--head == -1) head += N;
                                queueBuffer[head] = e.to;
                            }
                            visited[e.to] = 1;
                            prevEdge[e.to] = idx;
                            prevNode[e.to] = u;
                            distArray[e.to] = nd;
                        }
                    }
                }
                return visited[sink] != 0;
            }

            class P implements Comparable<P> {
                int node, priority;
                P(int n, int p) { node = n; priority = p; }
                public int compareTo(P other) { return Integer.compare(priority, other.priority); }
            }

            boolean dijkstraWithPotential() {
                visited = new int[N];
                distArray = new int[N];
                prevNode = new int[N];
                prevEdge = new int[N];
                Arrays.fill(distArray, INF);
                distArray[source] = 0;
                PriorityQueue<P> pq = new PriorityQueue<>();
                pq.add(new P(source, 0));
                while(!pq.isEmpty()) {
                    P current = pq.poll();
                    while(distArray[current.node] < current.priority) {
                        if(pq.isEmpty()) return false;
                        current = pq.poll();
                    }
                    visited[current.node] = 2;
                    for(int i = 0; i < edgeMatrix[current.node].length; i++) {
                        Edge e = edgeMatrix[current.node][i];
                        if(e.cap == 0) continue;
                        int reducedCost = e.cost + distArray[current.node] - distArray[e.to];
                        int newDist = current.priority + reducedCost;
                        if(newDist < distArray[e.to]) {
                            if(visited[e.to] == 2) return false;
                            pq.add(new P(e.to, newDist));
                            distArray[e.to] = newDist;
                            prevNode[e.to] = current.node;
                            prevEdge[e.to] = i;
                            visited[e.to] = 1;
                        }
                    }
                }
                return visited[sink] != 0;
            }

            int augmentFlow() {
                int pathFlow = INF;
                int node = sink;
                while(node != source) {
                    int parent = prevNode[node], idx = prevEdge[node];
                    pathFlow = Math.min(pathFlow, edgeMatrix[parent][idx].cap);
                    node = parent;
                }
                node = sink;
                while(node != source) {
                    int parent = prevNode[node], idx = prevEdge[node];
                    edgeMatrix[parent][idx].cap -= pathFlow;
                    edgeMatrix[node][edgeMatrix[parent][idx].rev].cap += pathFlow;
                    node = parent;
                }
                flow += pathFlow;
                return pathFlow;
            }

            void runAlgorithm() {
                initializePotential();
                while(performSPFA()) {
                    if(distArray[sink] >= INF - 1) break;
                    totalCost += (long)distArray[sink] * augmentFlow();
                }
            }

            void runAlgorithmWithPotential() {
                initializePotential();
                while(dijkstraWithPotential()) {
                    long reducedCost = distArray[sink] + (long)distArray[sink] - distArray[source];
                    if(reducedCost >= INF) break;
                    totalCost += reducedCost * augmentFlow();
                    for(int i = 0; i < N; i++) {
                        if(visited[i] != 0) {
                            potential[i] += distArray[i] - distArray[source];
                        }
                    }
                }
            }
        }

        void run(int test, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            int k = in.nextInt();
            int c = in.nextInt();
            int d = in.nextInt();
            int maxLevels = n + k;
            int sinkNode = n * maxLevels + 1;
            MinCostFlow network = new MinCostFlow(sinkNode + 1, 0, sinkNode);
            int[] freq = new int[n + 1], positions = new int[k + 1];
            for(int i = 1; i <= k; i++) {
                positions[i] = in.nextInt();
                freq[positions[i]]++;
            }
            for(int i = 1; i <= n; i++) {
                if(freq[i] > 0)
                    network.addEdge(0, i, freq[i], 0);
            }
            for(int i = 2; i <= n; i++) {
                for(int level = 0; level < maxLevels - 1; level++) {
                    network.addEdge(level * n + i, (level + 1) * n + i, k, c);
                }
            }
            for(int i = 1; i <= m; i++) {
                int u = in.nextInt();
                int v = in.nextInt();
                for(int level = 0; level < maxLevels - 1; level++) {
                    for(int p = 1; p <= k; p++) {
                        if(u != 1)
                            network.addEdge(level * n + u, (level + 1) * n + v, 1, d * (2 * p - 1) + c);
                        if(v != 1)
                            network.addEdge(level * n + v, (level + 1) * n + u, 1, d * (2 * p - 1) + c);
                    }
                }
            }
            for(int level = 1; level < maxLevels; level++) {
                network.addEdge(level * n + 1, sinkNode, k, 0);
            }
            network.packEdges();
            network.runAlgorithmWithPotential();
            if(network.flow != k)
                out.println("BUG");
            else
                out.println(network.totalCost);
        }
    }

    static class InputReader {
        BufferedReader reader;
        StringTokenizer tokenizer;
        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }
        String next() {
            while(tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if(line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch(IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }
        int nextInt() { return Integer.parseInt(next()); }
        long nextLong() { return Long.parseLong(next()); }
    }
}
